    overview:
      "Tensorlake sells a sandbox-native cloud rather than a generic serverless host: CPU sandboxes run as isolated MicroVMs that boot in hundreds of milliseconds, GPU sandboxes run under gVisor, and a separate Orchestration runtime handles long-running, crash-resumable workflows around them. The engineering pitch is the storage path. Sandboxes use block-based CAS images that fault content in on demand instead of copying a whole snapshot, which is why the vendor's SQLite benchmark on 2 vCPU / 4 GB finishes in 2.45s against 3.00s for Vercel, 3.92s for E2B, 4.66s for Modal and 5.51s for Daytona; those numbers are self-reported and the benchmark is the vendor's own. Snapshots can be cloned across machines, idle sandboxes suspend and resume without losing memory or filesystem state, and live migration moves a sandbox during maintenance with a few seconds of pause. The platform claims up to 5 million sandboxes per project. The developer surface is Python, TypeScript and Rust SDKs plus a `tl` CLI with contexts, exec, cp, ssh and network policy updates; webhooks deliver signed sandbox and application lifecycle events. GPU pools allocate H100 or A10 with per-pool warm capacity. Billing is genuinely per-use: active CPU only, with a disclosed 20% floor on allocated vCPU, snapshot storage by the GB-month, and free egress. Caveats: the service is proprietary even though the SDK repo is Apache-2.0, arbitrary Docker image references are not accepted without registering a sandbox image, and the performance claims are vendor-run.",
