    overview:
      "StackBlitz WebContainers run a Node.js environment and a POSIX-like filesystem inside the browser tab using WebAssembly, and that single decision changes the economics of the rest of this catalog. There is no server to schedule, no container to boot and no per-second bill, because the compute is the visitor's own machine. What you get instead is a runtime that behaves like a small Linux box for the JavaScript ecosystem: files, a shell, npm-compatible installs and a dev server, all started instantly with no cold start. The isolation boundary is the WebAssembly sandbox plus the browser's own process and origin model, not a kernel, which is why it is the right tool for interactive tutorials, in-product IDEs and browser-side coding agents, and the wrong one for running arbitrary Linux binaries or untrusted native code. It powers StackBlitz itself and the wave of browser IDEs after it, and it is licensed rather than metered by compute-hour: prototypes and proofs of concept need no commercial license, production use in a for-profit product requires one, and self-hosted, on-premises or VPC deployments with private npm registries and SAML2 SSO go through sales. The honest limitation is coverage: anything that needs a real kernel, Docker or a GPU is outside what a browser tab can do.",
