    overview:
      "nsjail is a low-level building block rather than a platform, and that is the whole point: it jails one process using Linux namespaces, resource limits and seccomp-bpf, in about the time it takes to fork. The isolation surface is unusually broad for a single tool. It clones UTS, mount, PID, IPC, network, user, cgroup and time namespaces, constrains the filesystem with chroot or pivot_root plus read-only mounts and custom /proc and tmpfs, caps CPU time, memory, file descriptors and process count through cgroups v1 or v2, and filters syscalls with Kafel policies. Networking gets its own treatment, with cloned or isolated Ethernet interfaces, MACVLAN support and userland networking through pasta. Three run modes cover the usual shapes: a TCP listener in inetd style, a standalone single run, and continuous re-execution for callers that stay resident. The boundary is the kernel, so it is cheaper than a VM and shares the kernel's attack surface, which is exactly the trade this catalog documents elsewhere. Configuration is protobuf files or plain arguments, and the build is the usual autoconf and make.",
