    overview:
      "kbox is an unusual point in the sandbox design space: instead of isolating a guest from the host kernel, it brings a real Linux kernel into the process. LKL — the Linux Kernel Library — is linked into the kbox binary, and syscalls are intercepted with seccomp, SIGSYS traps or binary rewriting and dispatched into that in-process kernel. The payoff is semantic accuracy without privileges: real ext4, real VFS, real procfs, so build tools and test suites behave the way they do on a server, without a container daemon or ptrace. The project's own security model is the most useful part of the README. It defines three deployment tiers rather than claiming one boundary fits all: kbox alone for trusted code, kbox plus namespaces or Landlock for agent tool execution with defense in depth, and kbox inside a microVM or gVisor for hostile, multi-tenant payloads. It also states plainly that LKL and the dispatch path share an address space with the guest, so a memory-safety bug there is exploitable. Treat it as an inner execution layer with excellent observability, and keep a real outer boundary around anything you would not run on a laptop.",
