    overview:
      "libkrun is the layer under a surprising number of the sandboxes in this catalog. It is a dynamic library, not a service: a program links it and gains the ability to boot a VM-backed process with KVM on Linux or Hypervisor.framework on macOS ARM64, through either a Rust or a C API. That is why Podman can run containers with a VM boundary through crun's krun handler, why krunkit gives macOS GPU-enabled lightweight VMs through venus, and why smolvm and nerdbox build their machines on it. The scope is deliberately small: a VMM plus the minimum emulated devices needed, with GPU support through virtio-gpu and Venus and some confidential-computing paths. Two caveats matter. The main branch is libkrun 2.0 with an intentionally unstable API and ABI, so production builds should track a stable-* branch. And the VM boundary does not automatically restrict host resources exposed through devices, so the embedding program has to limit permissions and paths, as the project's security model states.",
