        "This is one Docker container, not a VM: every service shares the host kernel. The project's quick start passes --security-opt seccomp=unconfined, which relaxes the container's syscall filter, so treat the boundary as a normal container and give it no host mounts or credentials you would not give any container. Bind port 8080 to 127.0.0.1 and set SANDBOX_API_KEY, otherwise the API, Jupyter and VNC are open to anyone who can reach the port.",
