    overview:
      "AIO Sandbox is a packaging play rather than a new isolation primitive: it puts the tools an agent usually needs into one Docker image with a shared filesystem, so a file downloaded in the browser is immediately visible to shell and file APIs. Inside one container it runs Chrome with CDP and VNC, a web terminal, VSCode Server, JupyterLab, a file API and an MCP hub exposing browser, file, shell and Markitdown servers. Everything is reached through one HTTP API on port 8080, and Python, TypeScript and Go SDKs wrap the same endpoints. The benefit is integration time: no wiring a browser service to a code service to a file service. The cost is isolation honesty. It is a container on the host kernel, its quick start disables seccomp filtering, and without SANDBOX_API_KEY all of those interfaces are unauthenticated. The project's own docs tell you to bind to 127.0.0.1 and put a proxy in front for cloud use. For untrusted multi-tenant code, put this image inside a VM or a stronger sandbox; for a single trusted agent workstation, it is a fast way to get the full toolbelt.",
