    overview:
      "Zeroboot removes boot from the critical path. A template VM pre-loads the runtime once and snapshots memory plus CPU state; every sandbox after that is a copy-on-write mapping of that snapshot into a new KVM VM, restoring CPU state in place. The repo publishes p50 0.79ms and p99 1.74ms spawn latency and ~265KB per sandbox. The trade-offs are explicit: one vCPU per fork, no networking inside the sandbox, and forks that share the template's CSPRNG state, so each userspace PRNG must reseed. Template changes need a fresh snapshot of about 15 seconds. It is Apache-2.0 and can be self-hosted on any KVM host; the managed API is in early access.",
