    overview:
      "SPACE — Sandboxed Platform for Agentic Code Execution — is the platform Perplexity built for agent and user code and then open sourced under Apache-2.0. Its unit is a Firecracker microVM created from an immutable template digest: an application creates a sandbox, opens a command session, reads stdout and stderr over a separate stream, then pauses, suspends, wakes or deletes it through a small HTTP API. The lifecycle is more granular than most peers: pause keeps VM memory resident for a fast wake, suspend snapshots memory and root filesystem and releases the VM, and after six idle hours the API suspends a sandbox on its own. Warm pools and base snapshots cut create latency, and the repo ships a Kind deployment plus an EKS reference. Teams already on E2B can point the tested Python `e2b` 2.21.1 client at the E2B Compatibility Wrapper instead of rewriting. Egress is default-deny with named operator profiles. The caveats: it is pre-1.0 with no tagged release, the deployment surface is heavy (PostgreSQL, S3-compatible storage, Kubernetes or direct workers), and the docs are written for operators rather than first-time users.",
