    overview:
      "Landrun is what firejail would look like if the kernel did the enforcement. A process sandboxes itself with Landlock, so any command can be given read paths, write paths, per-path execution rights, TCP and UDP connect/bind rules, IPC scoping and UNIX-socket control without root, containers or an LSM policy file. For agent work that means a plain CLI process can be capped at the project directory and the one API endpoint it needs. The tradeoff is explicit: Landlock restricts filesystem and network reach but shares the kernel and does not virtualize the host, so this is process isolation, not a microVM.",
