    overview:
      "OpenShell takes the position that an agent which cannot touch files, packages, APIs and credentials is not useful, so the answer is not to deny everything but to declare what each agent may touch and enforce it below the agent. Kernel controls confine file access and syscalls, and outbound connections are checked against a policy before they leave; the agent never holds real credentials, since a provider layer adds them on requests to approved endpoints. What separates it from the other policy wrappers in this catalog is the prover: a policy change is formally verified for the new access it would grant — a new host reachable with credentials, a new API method — and those changes wait for human review. The gateway runs locally, on Kubernetes with Helm (your CNI must enforce NetworkPolicy), or on NVIDIA Brev, and there are Python, TypeScript, Go and Rust SDKs. Released February 2026 under Apache-2.0 and moving into the CNCF.",
