      "Entra token authentication with a dedicated executor role",
      "File upload and download under /mnt/data, 128 MB per file",
      "220-second cap per code execution",
      "LangChain, LlamaIndex and Semantic Kernel integrations",
      "Azure Monitor and Log Analytics for custom containers",
