    overview:
      "Wasmtime is the reference implementation most other agent-sandbox products embed rather than compete with: a JIT and AOT WebAssembly runtime from the Bytecode Alliance. For sandboxing it offers the cheapest boundary in the catalog, with no guest kernel, no container image and microsecond instantiation, and the capability model is the security story, since a module gets only the host functions and WASI resources handed to it. Fuel metering and epoch-based interruption give a hard CPU budget for untrusted loops, which is the piece most in-process interpreters lack. The limit is shape: it runs Wasm modules, not shell commands, so an agent that needs apt, pip or a persistent process has to bring a precompiled module or step up to a microVM. It is also a library, not a service, so quotas, scheduling and warm pools are yours to build.",
