      networkIsolation:
        "Network is denied by default and mediated by host-side HTTP and SOCKS5 proxies. On Linux the sandboxed process has no network namespace, so traffic must use the bind-mounted proxy sockets. On macOS the Seatbelt profile permits only a localhost proxy port. On Windows a WFP filter blocks the srt-sandbox account except loopback to the proxy range. Filesystem writes are allow-only, reads are deny-then-allow, and Unix socket access is filtered. This is a process-level OS sandbox, not a VM: the workload still shares the host kernel, so it is a boundary against agent mistakes and untrusted tools, not a substitute for a microVM against a kernel exploit.",
