    overview:
      "Anthropic Sandbox Runtime, or srt, takes the boundary Claude Code already uses and makes it a standalone wrapper for any process. Instead of starting a container or a VM, it applies the host's own sandboxing primitives to the process tree: a generated Seatbelt profile on macOS, bubblewrap with the network namespace removed on Linux, and a dedicated srt-sandbox user plus a Windows Filtering Platform fence on Windows. Filesystem writes are denied unless explicitly allowed, reads can be denied broadly and re-allowed narrowly, and all network traffic is forced through host-side HTTP and SOCKS5 proxies that enforce domain allowlists. The same boundary can wrap a bash command, a local MCP server or any long-running agent, and macOS violation logs surface blocked operations in real time. It is a research preview for Claude Code, so config and API can change. The security trade is deliberate: this is a process on your existing kernel, not hardware isolation, so it confines agent mistakes, credential theft and unwanted egress, but it does not contain a kernel exploit. The README also documents Windows token and system-service paths that can carry traffic outside the fence.",
