    overview:
      "x11docker solves a narrower problem than most entries here: containers have no display server, so GUI apps are awkward to isolate. The project is a Bash wrapper that starts a dedicated X server or Wayland compositor for the session, runs the graphical app or whole desktop inside Docker, Podman or another backend, and applies a set of X11 leak protections and container hardening on top. That makes it possible to run an old browser, Wine application or full XFCE desktop in a disposable environment without handing it the host's display socket. Options cover desktop vs seamless mode, GPU acceleration, clipboard, audio, webcam, printers, shared folders, init systems and DBus, and the script prints warnings when one of those weakens isolation. It supports Docker Engine, Podman and nerdctl; Docker Desktop's VM based setup is only experimental. The honest limits: this is a container on the host kernel, not a VM, and options such as --hostdisplay, --gpu, --clipboard or shared audio undo much of the protection. The project itself says no sandbox is perfect and does not recommend it for obviously malicious software.",
