    overview:
      "Coi (Code on Incus) takes the opposite stance to the read-only prompt sandboxes: give the coding agent a real machine, just not yours. It launches an Incus system container with root, systemd, native Docker, package managers and services, mounts the project at /workspace with workable file ownership, and keeps host credentials out unless a mount or forward is explicitly granted. The interesting part is the monitoring layer. Kernel-level detection watches for reverse shells, command-and-control traffic, exfiltration and DNS tunnelling, then pauses or kills the container itself, and nftables egress has open, restricted and allow-list modes with DNS pinning. Profiles, parallel slots per project, ephemeral-or-persistent boxes, read-only git hooks, a branch guard against pushing to main and JSONL threat logs round it out. The trade-off is explicit in the architecture: Incus containers share the host kernel, so this is a strong operational sandbox with unusually good observability, not a hardware isolation boundary. It also assumes Linux with Incus, with macOS supported only through Colima or Lima.",
