    overview:
      "Cupcake answers a question that sits next to isolation rather than inside it: given that the agent runs, what is it allowed to do? Instead of putting rules in a prompt and hoping the model complies, it hooks the harness at the action boundary, enriches each proposed call with signals such as the current branch or CI result, and evaluates an OPA/Rego policy compiled to Wasm. The decision comes back as allow, modify, block, warn or require review, with feedback the agent can use to correct itself. The useful consequence is that operational rules stop consuming context and become testable code; the project ships per-harness policy trees and first-class coverage for Claude Code, Cursor, Factory AI and OpenCode, plus an optional LLM-as-judge for prose-shaped rules. The limits matter as much as the feature list. This is not a sandbox: it does not create a kernel or VM boundary, does not filter egress, and only sees actions the harness exposes through hooks. Use it to enforce repo conventions, block dangerous flags and gate pushes; pair it with a real isolation layer for hostile code.",
